--
-- Table structure for table `atenciones`
--

DROP TABLE IF EXISTS `atenciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `atenciones` (
  `id_atencion` bigint(20) NOT NULL AUTO_INCREMENT,
  `id_paciente` bigint(20) NOT NULL,
  `id_profesional` int(11) NOT NULL,
  `fecha_atencion` datetime NOT NULL,
  `id_tipo_consulta` int(11) NOT NULL,
  `duracion_minutos` int(11) DEFAULT 30,
  `motivo_consulta` text DEFAULT NULL,
  `anamnesis` text DEFAULT NULL,
  `diagnostico` text DEFAULT NULL,
  `indicaciones` text DEFAULT NULL,
  `signos_vitales` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`signos_vitales`)),
  `examenes_solicitados` text DEFAULT NULL,
  `derivaciones` text DEFAULT NULL,
  `recetas` text DEFAULT NULL,
  `estado` enum('Programada','En Curso','Completada','Cancelada','No Asistió') DEFAULT 'Programada',
  `lugar` varchar(100) DEFAULT NULL,
  `id_centro` int(11) DEFAULT NULL,
  `id_establecimiento` int(11) DEFAULT NULL,
  `id_departamento` int(11) DEFAULT NULL,
  `notas_internas` text DEFAULT NULL,
  `proxima_cita` date DEFAULT NULL,
  `archivo_adjunto` varchar(255) DEFAULT NULL,
  `fecha_creacion` timestamp NOT NULL DEFAULT current_timestamp(),
  `fecha_actualizacion` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `registrado_por` bigint(20) DEFAULT NULL,
  `actualizado_por` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id_atencion`),
  KEY `id_establecimiento` (`id_establecimiento`),
  KEY `id_departamento` (`id_departamento`),
  KEY `registrado_por` (`registrado_por`),
  KEY `actualizado_por` (`actualizado_por`),
  KEY `idx_atencion_paciente` (`id_paciente`),
  KEY `idx_atencion_profesional` (`id_profesional`),
  KEY `idx_atencion_fecha` (`fecha_atencion`),
  KEY `idx_atencion_tipo` (`id_tipo_consulta`),
  KEY `idx_atencion_estado` (`estado`),
  KEY `idx_atencion_centro` (`id_centro`,`id_establecimiento`),
  CONSTRAINT `atenciones_ibfk_1` FOREIGN KEY (`id_profesional`) REFERENCES `profesionales` (`id_profesional`),
  CONSTRAINT `atenciones_ibfk_2` FOREIGN KEY (`id_centro`) REFERENCES `centros_salud` (`id_centro`),
  CONSTRAINT `atenciones_ibfk_3` FOREIGN KEY (`id_establecimiento`) REFERENCES `establecimientos` (`id_establecimiento`),
  CONSTRAINT `atenciones_ibfk_4` FOREIGN KEY (`id_departamento`) REFERENCES `departamentos` (`id_departamento`),
  CONSTRAINT `atenciones_ibfk_5` FOREIGN KEY (`registrado_por`) REFERENCES `usuarios` (`id_usuario`),
  CONSTRAINT `atenciones_ibfk_6` FOREIGN KEY (`actualizado_por`) REFERENCES `usuarios` (`id_usuario`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `atenciones`
--

LOCK TABLES `atenciones` WRITE;
/*!40000 ALTER TABLE `atenciones` DISABLE KEYS */;
/*!40000 ALTER TABLE `atenciones` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `auditoria_modulos`
--

DROP TABLE IF EXISTS `auditoria_modulos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `auditoria_modulos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `module_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'IDs de módulos afectados' CHECK (json_valid(`module_ids`)),
  `action` enum('assign','remove','modify','create','delete','activate','deactivate') NOT NULL,
  `assigned_by` varchar(100) NOT NULL,
  `target_user_id` int(11) DEFAULT NULL COMMENT 'Usuario afectado (si aplica)',
  `reason` varchar(255) DEFAULT NULL,
  `old_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Valores anteriores' CHECK (json_valid(`old_values`)),
  `new_values` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Valores nuevos' CHECK (json_valid(`new_values`)),
  `timestamp` timestamp NULL DEFAULT current_timestamp(),
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `session_id` varchar(128) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_audit_user` (`user_id`,`timestamp`),
  KEY `idx_audit_target` (`target_user_id`,`timestamp`),
  KEY `idx_audit_action` (`action`,`timestamp`),
  KEY `idx_audit_timestamp` (`timestamp`),
  KEY `idx_audit_assigned_by` (`assigned_by`,`timestamp`)
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Auditoría completa de operaciones con módulos';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `auditoria_modulos`
--

