DROP TABLE IF EXISTS `bioest_predicciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `bioest_predicciones` (
  `id_prediccion` bigint(20) NOT NULL AUTO_INCREMENT,
  `id_modelo` bigint(20) NOT NULL,
  `fecha_prediccion` datetime NOT NULL DEFAULT current_timestamp(),
  `periodo_prediccion` date NOT NULL,
  `valor_predicho` decimal(15,4) NOT NULL,
  `intervalo_confianza_min` decimal(15,4) DEFAULT NULL,
  `intervalo_confianza_max` decimal(15,4) DEFAULT NULL,
  `probabilidad` decimal(5,4) DEFAULT 1.0000,
  `variables_utilizadas` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`variables_utilizadas`)),
  `confidence_score` decimal(5,4) DEFAULT 0.0000,
  `valor_real` decimal(15,4) DEFAULT NULL,
  `error_prediccion` decimal(15,4) DEFAULT NULL,
  `validado` tinyint(1) DEFAULT 0,
  PRIMARY KEY (`id_prediccion`),
  KEY `idx_prediccion_periodo` (`periodo_prediccion`,`fecha_prediccion`),
  KEY `idx_prediccion_modelo` (`id_modelo`,`periodo_prediccion`),
  CONSTRAINT `bioest_predicciones_ibfk_1` FOREIGN KEY (`id_modelo`) REFERENCES `bioest_modelos_predictivos` (`id_modelo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
