/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tr_actualizar_tamaño_carpeta_insert` AFTER INSERT ON `drive_archivos` FOR EACH ROW BEGIN
  
  UPDATE drive_carpetas
  SET 
    tamaño_total      = tamaño_total + NEW.tamaño_bytes,
    cantidad_archivos = cantidad_archivos + 1
  WHERE id_carpeta = NEW.id_carpeta;

  
  UPDATE drive_carpetas
  SET tamaño_total = tamaño_total + NEW.tamaño_bytes
  WHERE id_carpeta IN (
    SELECT DISTINCT c2.id_carpeta
    FROM drive_carpetas c1
    JOIN drive_carpetas c2 
      ON c1.ruta_completa LIKE CONCAT(c2.ruta_completa, '%')
    WHERE c1.id_carpeta = NEW.id_carpeta
      AND c2.id_carpeta != NEW.id_carpeta
  );
END */;;
