CREATE TABLE `emergencias` (
  `id_emergencia` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'Clave primaria única para cada registro de emergencia',
  `id_tipo_emergencia` int(11) DEFAULT NULL COMMENT 'FK hacia tipos_emergencia.id_tipo para clasificar el tipo de emergencia',
  `nombre` varchar(200) NOT NULL COMMENT 'Título o nombre breve de la emergencia',
  `descripcion` text DEFAULT NULL COMMENT 'Descripción detallada del evento de emergencia',
  `ubicacion` varchar(255) DEFAULT NULL COMMENT 'Ubicación geográfica o dirección donde ocurrió la emergencia',
  `fecha_inicio` datetime NOT NULL COMMENT 'Marca de tiempo de inicio/reporto de la emergencia',
  `fecha_fin` datetime DEFAULT NULL COMMENT 'Marca de tiempo de resolución; NULL si aún no finaliza',
  `nivel_severidad` enum('CRÍTICA','ALTA','MEDIA','BAJA') NOT NULL DEFAULT 'MEDIA' COMMENT 'Nivel de severidad asignado a la emergencia',
  `estado` enum('ABIERTO','EN_PROCESO','RESUELTO','CANCELADO') NOT NULL DEFAULT 'ABIERTO' COMMENT 'Estado actual de la emergencia',
  `activo` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Flag para habilitar/deshabilitar el registro (1=activo, 0=inactivo)',
  `fecha_creacion` datetime NOT NULL DEFAULT current_timestamp() COMMENT 'Fecha de creación del registro',
  `fecha_actualizacion` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'Última fecha en que se modificó el registro',
  `created_by` bigint(20) DEFAULT NULL COMMENT 'ID de usuario que creó el registro (FK a usuarios.id_usuario)',
  `updated_by` bigint(20) DEFAULT NULL COMMENT 'ID de usuario que actualizó por última vez (FK a usuarios.id_usuario)',
  PRIMARY KEY (`id_emergencia`),
  KEY `idx_emg_id_tipo` (`id_tipo_emergencia`),
  KEY `idx_emg_fecha_inicio` (`fecha_inicio`),
  KEY `idx_emg_nivel_severidad` (`nivel_severidad`),
  KEY `idx_emg_estado` (`estado`),
  KEY `idx_emg_activo` (`activo`),
  KEY `idx_emg_created_by` (`created_by`),
  KEY `idx_emg_updated_by` (`updated_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Registro maestro de todos los eventos de emergencia, con trazabilidad de auditoría y atributos de ubicación, estado y severidad';
