  KEY `idx_eal_activo` (`activo`),
  KEY `idx_eal_created_by` (`created_by`),
  KEY `idx_eal_updated_by` (`updated_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Registro de alertas asociadas a una emergencia';
