--
-- Table structure for table `iaaps_datos_mensuales`
--

DROP TABLE IF EXISTS `iaaps_datos_mensuales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `iaaps_datos_mensuales` (
  `id_dato` bigint(20) NOT NULL AUTO_INCREMENT,
  `id_iaap` int(11) DEFAULT NULL,
  `id_centro` int(11) DEFAULT NULL,
  `id_establecimiento` int(11) DEFAULT NULL,
  `ano` year(4) NOT NULL,
  `mes` tinyint(4) NOT NULL,
  `numerador` decimal(15,4) DEFAULT NULL,
  `denominador` decimal(15,4) DEFAULT NULL,
  `resultado_calculado` decimal(15,4) GENERATED ALWAYS AS (if(`denominador` = 0 or `denominador` is null,0,`numerador` / `denominador` * 100)) STORED,
  `valor_meta` decimal(8,4) DEFAULT NULL,
  `ponderacion` decimal(5,2) NOT NULL DEFAULT 100.00,
  `porcentaje_cumplimiento` decimal(10,6) GENERATED ALWAYS AS (if(`valor_meta` = 0 or `valor_meta` is null,0,`resultado_calculado` / `valor_meta` * `ponderacion`)) STORED,
  `estado_validacion` enum('PENDIENTE','VALIDADO','RECHAZADO') NOT NULL DEFAULT 'PENDIENTE',
  `observaciones` text DEFAULT NULL,
