INSERT INTO `indicadores_salud` VALUES (25,'IND-1','Porcentaje de niños y niñas de 12 a 23 meses con riesgo del desarrollo psicomotor recuperados','Niños 12 a 23 meses diagnosticados en primera evaluación con RDSM de octubre a septiembre - derivados - trasladados.','N° de niñas y niños de 12 a 23 meses diagnosticados con riesgo del desarrollo psicomotor (DSM) recuperados en 2025','N° de niñas y niños de 12 a 23 meses diagnosticados con RDSM entre oct 2024 y sep 2025','REM A03 – Sección A.2','REM A03 – Sección A.2','J26 + K26 + M26 + L26 + J28 + K28 + L28 + M28','J23 + K23 + L23 + M23 - (J37 + K37 + L37 + M37 + J40 + K40 + L40 + M40)','(N° recuperados DSM / N° diagnosticados con RDSM) * 100','%',87.10,80.00,100.00,NULL,NULL,1,'2025-01-05 00:23:44','2025-05-23 15:37:10'),(26,'IND-2','Porcentaje personas de 25 a 64 años con tamizaje para la detección precoz de Cáncer de Cuello Uterino','Cobertura de PAP vigente en mujeres de 25 a 64 años','N° de personas de 25 a 64 años con PAP o Test de VPH vigente a diciembre 2025','N° de personas de 25 a 64 años inscritas validadas por FONASA en 2025','REM P12 – Sección A','FONASA','B11 + B12 + ... + C18','Dato único FONASA','(N° personas con PAP o VPH vigente / N° personas inscritas 25-64 años) * 100','%',80.00,80.00,100.00,NULL,NULL,1,'2025-01-05 00:23:44','2025-05-23 15:37:10'),(27,'IND-3.A','Porcentaje de niños de 0 a 9 años en control con enfoque de riesgo odontológico y pauta 0 aplicada','Control odontológico en población infantil','N° de niños y niñas de 0 a 9 años en control con enfoque de riesgo odontológico y pauta CERO aplicada','N° total de niños y niñas inscritos validados de 0 a 9 años, año 2025','REM A03 – Sección D.7','FONASA','F206 a W206 + F207 a Y207','Dato único poblacional FONASA','(N° niños 0-9 años en control con pauta CERO / N° total niños 0-9 años inscritos) * 100','%',45.00,45.00,100.00,NULL,NULL,1,'2025-01-05 00:23:44','2025-05-23 15:37:10'),(28,'IND-3.B','Porcentaje de Niños y niñas de 6 años libres de caries','Índice de niños sin caries a los 6 años','N° de niños y niñas de 6 años con CEOD igual a 0 en 2025','N° total de niños y niñas inscritos validados de 6 años, año 2025','REM A09 – Sección C','FONASA','S52 + T52','Dato único FONASA','(N° niños de 6 años con CEOD=0 / N° total niños de 6 años inscritos) * 100','%',20.00,20.00,100.00,NULL,NULL,1,'2025-01-05 00:23:44','2025-05-23 15:37:10'),(29,'IND-4.A','Cobertura efectiva de tratamiento de DM2 en personas de 15 años y más','Control efectivo de diabetes tipo 2','N° de personas con DM2 (15-79 años) con HbA1c <7% + DM2 (80+ años) con HbA1c <8%, último control vigente 12 meses','N° Total de personas de 15 años y más con DM2 estimadas según prevalencia (ENS 2016-17)','REM P04 – Sección B','FONASA','C36 + C37','Estimación ENS 2016-17','[(DM2 15-79 con HbA1c<7%) + (DM2 80+ con HbA1c<8%)] / Total estimado con DM2 * 100','%',29.00,29.00,100.00,NULL,NULL,1,'2025-01-05 00:23:44','2025-05-23 15:37:10'),(30,'IND-4.B','Evaluación anual de los pies en personas con diabetes bajo control de 15 y más años','Evaluación podológica en diabéticos','N° de personas con DM2 (15+) bajo control con evaluación de pie diabético vigente en 12 meses','N° de personas de 15+ con DM2 bajo control en últimos 12 meses','REM P04','REM P04 – Sección A','C61 + C62 + C63 + C64','C17','(N° con evaluación de pie diabético / N° DM2 bajo control en 12 meses) * 100','%',88.84,88.84,100.00,NULL,NULL,1,'2025-01-05 00:23:44','2025-05-23 15:37:10'),(31,'IND-5','Cobertura efectiva de HTA en personas de 15 años y más','Control efectivo de hipertensión arterial','N° personas con HTA (15-79) con PA <140/90 mmHg + (80+) con PA <150/90 mmHg, último control vigente','Total de personas de 15+ con HTA estimadas según prevalencia (ENS 2016-17)','REM P04','FONASA','C34 + C35','Estimación ENS 2016-17','[(HTA 15-79 con PA<140/90) + (HTA 80+ con PA<150/90)] / Total estimado con HTA * 100','%',42.00,42.00,100.00,NULL,NULL,1,'2025-01-05 00:23:44','2025-05-23 15:37:10'),(32,'IND-6','Prevalencia de lactancia materna exclusiva en niños y niñas al sexto mes de vida','Lactancia materna exclusiva hasta los 6 meses','N° de niños y niñas con control de salud del sexto mes que recibieron lactancia materna exclusiva','N° de niños y niñas con control de salud del sexto mes realizado en 2025','REM A03 – Sección A.5','REM A03 – Sección A.5','H61','H67','(N° con lactancia materna exclusiva al 6° mes / N° controles de salud del 6° mes) * 100','%',60.00,60.00,100.00,NULL,NULL,1,'2025-01-05 00:23:44','2025-05-23 15:37:10'),(33,'IND-7','Cobertura efectiva de tratamiento en enfermedades respiratorias crónicas(asma y EPOC) en personas de 5 años y más','Control de enfermedades respiratorias crónicas','N° personas con EPOC 40+ años con control adecuado + personas con asma 5+ años con controlado','N° total de personas con EPOC (40+) y asma (5+), esperadas según prevalencia nacional','REM P03 – Sección D','FONASA','C59 - (F59 + G59) + C63','Dato único FONASA','[(EPOC 40+ con control adecuado) + (Asma 5+ con controlado)] / Total estimado con EPOC y Asma * 100','%',13.58,13.58,100.00,NULL,NULL,1,'2025-01-05 00:23:44','2025-05-23 15:37:10'),(34,'IND-8','Plan de Salud Comunitaria elaborado, ejecutado y evaluado participativamente.','Plan de participación social del establecimiento',NULL,NULL,NULL,NULL,NULL,NULL,'','%',100.00,100.00,100.00,NULL,NULL,1,'2025-01-05 00:23:44','2025-04-16 14:09:44');
/*!40000 ALTER TABLE `indicadores_salud` ENABLE KEYS */;
