/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `actualizar_estadisticas_mensaje_enviado` AFTER INSERT ON `mensajes` FOR EACH ROW BEGIN
    INSERT INTO estadisticas_chat (id_usuario, fecha_estadistica, mensajes_enviados)
    VALUES (NEW.id_remitente, DATE(NEW.fecha_envio), 1)
    ON DUPLICATE KEY UPDATE 
        mensajes_enviados = mensajes_enviados + 1;
        
    INSERT INTO estadisticas_chat (id_usuario, fecha_estadistica, mensajes_recibidos)
    VALUES (NEW.id_destinatario, DATE(NEW.fecha_envio), 1)
    ON DUPLICATE KEY UPDATE 
        mensajes_recibidos = mensajes_recibidos + 1;
END */;;
