  KEY `idx_creado_por` (`creado_por`),
  KEY `idx_config_activo_tipo` (`activo`,`tipo_evento`),
  CONSTRAINT `fk_mensajes_auto_usuario` FOREIGN KEY (`creado_por`) REFERENCES `usuarios` (`id_usuario`) ON DELETE SET NULL ON UPDATE CASCADE
