  KEY `idx_estado_envio` (`estado_envio`),
  KEY `idx_fecha_envio` (`fecha_envio`),
  KEY `idx_envios_mensaje_estado` (`id_mensaje`,`estado_envio`),
  CONSTRAINT `fk_envio_mensaje` FOREIGN KEY (`id_mensaje`) REFERENCES `mensajes_sistema` (`id_mensaje`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_envio_usuario` FOREIGN KEY (`id_destinatario`) REFERENCES `usuarios` (`id_usuario`) ON DELETE SET NULL ON UPDATE CASCADE
