INSERT INTO `mensajes_plantillas` VALUES (1,'Cumpleaños Estándar','Celebraciones','cumpleanos','¡Feliz Cumpleaños {nombre_completo}!','Estimado/a {nombre_completo},\n\nEn este día tan especial queremos desearte un muy feliz cumpleaños.\n\nQue este nuevo año de vida esté lleno de alegría, salud y éxitos profesionales.\n\nTodo el equipo de INFOGES Curicó te envía sus mejores deseos.\n\n¡Feliz cumpleaños!','<div style=\"text-align: center; padding: 20px;\"><h2 style=\"color: #FF6B6B;\">🎉 ¡Feliz Cumpleaños {nombre_completo}! 🎂</h2><p style=\"font-size: 16px; line-height: 1.6; color: #0B2E5A;\">En este día tan especial queremos desearte un muy <strong>feliz cumpleaños</strong>.</p><p style=\"font-size: 16px; line-height: 1.6; color: #0B2E5A;\">Que este nuevo año de vida esté lleno de <em>alegría, salud y éxitos profesionales</em>.</p><p style=\"font-size: 16px; line-height: 1.6; color: #0B2E5A;\">Todo el equipo de <strong>INFOGES Curicó</strong> te envía sus mejores deseos.</p><div style=\"margin: 30px 0; padding: 20px; background: linear-gradient(135deg, #FFE066, #FF6B6B); border-radius: 10px;\"><h3 style=\"margin: 0; color: white; text-shadow: 0 2px 4px rgba(0,0,0,0.3);\">¡Feliz cumpleaños!</h3></div></div>','[\"nombre\", \"apellidos\", \"nombre_completo\", \"edad\", \"centro\", \"cargo\"]',NULL,1,0,NULL,'2025-08-29 12:15:01','2025-08-29 12:15:01'),(2,'Día de la Madre','Días Especiales','felicitacion','Feliz Día de la Madre','Queridas mamás del equipo de salud,\n\nEn este día tan especial queremos reconocer y celebrar su invaluable labor como madres y profesionales de la salud.\n\nSu dedicación, amor y compromiso son una inspiración para todos nosotros.\n\n¡Feliz Día de la Madre!','<div style=\"text-align: center; padding: 20px; background: linear-gradient(135deg, #FFF5F5, #FEF2F2);\"><h2 style=\"color: #EC4899;\">💐 Feliz Día de la Madre 💕</h2><p style=\"font-size: 16px; line-height: 1.8; color: #0B2E5A;\">Queridas mamás del equipo de salud,</p><p style=\"font-size: 16px; line-height: 1.8; color: #0B2E5A;\">En este día tan especial queremos <strong>reconocer y celebrar</strong> su invaluable labor como madres y profesionales de la salud.</p><p style=\"font-size: 16px; line-height: 1.8; color: #0B2E5A;\">Su <em>dedicación, amor y compromiso</em> son una inspiración para todos nosotros.</p><div style=\"margin: 20px 0; padding: 15px; background: #EC4899; border-radius: 8px; color: white;\"><strong>¡Feliz Día de la Madre!</strong></div></div>','[\"nombre\", \"apellidos\", \"nombre_completo\", \"centro\"]',NULL,1,0,NULL,'2025-08-29 12:15:01','2025-08-29 12:15:01'),(3,'Día del Padre','Días Especiales','felicitacion','Feliz Día del Padre','Estimados papás del equipo INFOGES,\n\nEn su día queremos reconocer su esfuerzo diario como padres y profesionales comprometidos con la salud de nuestra comunidad.\n\nSu ejemplo de dedicación y responsabilidad es admirable.\n\n¡Feliz Día del Padre!','<div style=\"text-align: center; padding: 20px; background: linear-gradient(135deg, #F0F9FF, #E0F2FE);\"><h2 style=\"color: #0284C7;\">👨‍⚕️ Feliz Día del Padre 👔</h2><p style=\"font-size: 16px; line-height: 1.8; color: #0B2E5A;\">Estimados papás del equipo INFOGES,</p><p style=\"font-size: 16px; line-height: 1.8; color: #0B2E5A;\">En su día queremos <strong>reconocer su esfuerzo diario</strong> como padres y profesionales comprometidos con la salud de nuestra comunidad.</p><p style=\"font-size: 16px; line-height: 1.8; color: #0B2E5A;\">Su ejemplo de <em>dedicación y responsabilidad</em> es admirable.</p><div style=\"margin: 20px 0; padding: 15px; background: #0284C7; border-radius: 8px; color: white;\"><strong>¡Feliz Día del Padre!</strong></div></div>','[\"nombre\", \"apellidos\", \"nombre_completo\", \"centro\", \"cargo\"]',NULL,1,0,NULL,'2025-08-29 12:15:01','2025-08-29 12:15:01'),(4,'Fiestas Patrias Chile','Días Especiales','felicitacion','Felices Fiestas Patrias','Estimado equipo INFOGES Curicó,\n\nEn estas Fiestas Patrias queremos celebrar junto a ustedes el orgullo de ser chilenos y el compromiso con nuestra patria.\n\nQue disfruten de estos días junto a sus familias.\n\n¡Viva Chile!','<div style=\"text-align: center; padding: 20px; background: linear-gradient(135deg, #FEF3C7, #FDE68A);\"><h2 style=\"color: #DC2626;\">🇨🇱 Felices Fiestas Patrias 🎊</h2><p style=\"font-size: 16px; line-height: 1.8; color: #0B2E5A;\">Estimado equipo INFOGES Curicó,</p><p style=\"font-size: 16px; line-height: 1.8; color: #0B2E5A;\">En estas Fiestas Patrias queremos celebrar junto a ustedes <strong>el orgullo de ser chilenos</strong> y el compromiso con nuestra patria.</p><p style=\"font-size: 16px; line-height: 1.8; color: #0B2E5A;\">Que disfruten de estos días junto a sus familias.</p><div style=\"margin: 20px 0; padding: 15px; background: linear-gradient(90deg, #DC2626, #1D4ED8, #DC2626); border-radius: 8px; color: white;\"><strong>¡Viva Chile!</strong></div></div>','[\"nombre\", \"apellidos\", \"nombre_completo\"]',NULL,1,0,NULL,'2025-08-29 12:15:01','2025-08-29 12:15:01');
/*!40000 ALTER TABLE `mensajes_plantillas` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `mensajes_sistema`
--

DROP TABLE IF EXISTS `mensajes_sistema`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `mensajes_sistema` (
  `id_mensaje` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `tipo_mensaje` enum('manual','automatico') NOT NULL DEFAULT 'manual' COMMENT 'Tipo de mensaje',
  `titulo` varchar(255) NOT NULL COMMENT 'Título del mensaje',
  `contenido` text NOT NULL COMMENT 'Contenido en texto plano',
  `contenido_html` longtext DEFAULT NULL COMMENT 'Contenido con formato HTML',
  `adjuntos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Archivos adjuntos en formato JSON' CHECK (json_valid(`adjuntos`)),
  `destinatarios` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Lista de destinatarios (JSON)' CHECK (json_valid(`destinatarios`)),
  `filtros_destinatarios` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Filtros aplicados para destinatarios' CHECK (json_valid(`filtros_destinatarios`)),
  `fecha_programada` datetime DEFAULT NULL COMMENT 'Fecha programada para envío',
  `fecha_envio` datetime DEFAULT NULL COMMENT 'Fecha de envío real',
  `enviado_por` bigint(20) DEFAULT NULL COMMENT 'Usuario que envió',
  `estado` enum('borrador','programado','enviando','enviado','error') NOT NULL DEFAULT 'borrador',
  `total_destinatarios` int(11) NOT NULL DEFAULT 0,
  `total_enviados` int(11) NOT NULL DEFAULT 0,
  `total_errores` int(11) NOT NULL DEFAULT 0,
  `observaciones` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_mensaje`),
  KEY `idx_tipo_mensaje` (`tipo_mensaje`),
  KEY `idx_estado` (`estado`),
  KEY `idx_fecha_envio` (`fecha_envio`),
  KEY `idx_enviado_por` (`enviado_por`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_mensajes_tipo_estado_fecha` (`tipo_mensaje`,`estado`,`created_at`),
  CONSTRAINT `fk_mensajes_usuario` FOREIGN KEY (`enviado_por`) REFERENCES `usuarios` (`id_usuario`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

