  `fecha_publicacion` datetime DEFAULT current_timestamp(),
  `fecha_expiracion` datetime DEFAULT NULL,
  `id_autor` bigint(20) DEFAULT NULL,
  `autor_invitado` varchar(100) DEFAULT NULL,
  `id_centro` int(11) DEFAULT NULL,
  `id_establecimiento` int(11) DEFAULT NULL,
  `categoria` enum('General','Salud','Campañas','Capacitación','Eventos','Administrativo') DEFAULT NULL,
  `tipo_noticia` enum('Estándar','Reportaje','Entrevista','Análisis','Opinión') DEFAULT 'Estándar',
  `destacada` tinyint(1) DEFAULT 0,
  `destacada_home` tinyint(1) DEFAULT 0,
  `destacada_categoria` tinyint(1) DEFAULT 0,
  `activa` tinyint(1) DEFAULT 1,
  `imagen_premium` tinyint(1) DEFAULT 0,
  `imagen_mejorada_url` varchar(255) DEFAULT NULL,
  `visitas` int(11) DEFAULT 0,
  `compartidos` int(11) NOT NULL DEFAULT 0,
  `contador_compartidos` int(11) DEFAULT 0,
  `contador_comentarios` int(11) DEFAULT 0,
  `calificacion_promedio` decimal(3,2) DEFAULT 0.00,
  `tags` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tags`)),
  `tiempo_lectura` int(11) DEFAULT NULL,
  `metadatos_seo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadatos_seo`)),
  `prioridad` enum('alta','media','normal') NOT NULL DEFAULT 'normal',
  PRIMARY KEY (`id_noticia`),
  KEY `id_autor` (`id_autor`),
  KEY `id_centro` (`id_centro`),
  KEY `id_establecimiento` (`id_establecimiento`),
  KEY `idx_noticias_fecha` (`fecha_publicacion`),
  KEY `idx_noticias_categoria` (`categoria`),
  KEY `idx_noticias_destacada` (`destacada`),
  KEY `idx_noticias_tipo` (`tipo_noticia`),
  KEY `idx_noticias_destacadas` (`destacada`,`destacada_home`,`destacada_categoria`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
