--
-- Table structure for table `notificaciones`
--

DROP TABLE IF EXISTS `notificaciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `notificaciones` (
  `id_notificacion` bigint(20) NOT NULL AUTO_INCREMENT,
  `id_usuario` bigint(20) DEFAULT NULL,
  `id_usuario_origen` bigint(20) DEFAULT NULL,
  `titulo` varchar(255) NOT NULL,
  `mensaje` text DEFAULT NULL,
  `datos_adicionales` longtext DEFAULT NULL,
  `accion_requerida` tinyint(1) NOT NULL DEFAULT 0,
  `fecha_expiracion` datetime DEFAULT NULL,
  `prioridad` enum('low','normal','high','urgent') NOT NULL DEFAULT 'normal',
  `canal_entrega` set('web','email','sms','push') NOT NULL DEFAULT 'web',
  `intentos_entrega` int(3) NOT NULL DEFAULT 0,
  `entregada` tinyint(1) NOT NULL DEFAULT 0,
  `tipo` enum('SISTEMA','ALERTA','ADVERTENCIA','INFO') NOT NULL,
  `estado_lectura` tinyint(1) DEFAULT 0,
  `id_centro` int(11) DEFAULT NULL,
  `id_establecimiento` int(11) DEFAULT NULL,
  `fecha_creacion` timestamp NOT NULL DEFAULT current_timestamp(),
  `fecha_lectura` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_notificacion`),
  KEY `id_centro` (`id_centro`),
  KEY `id_establecimiento` (`id_establecimiento`),
  KEY `idx_origen` (`id_usuario_origen`),
  KEY `idx_tipo` (`tipo`),
  KEY `idx_leida` (`estado_lectura`),
  KEY `idx_prioridad` (`prioridad`),
  KEY `idx_fecha` (`fecha_creacion`),
  KEY `fk_notif_destino` (`id_usuario`)
) ENGINE=InnoDB AUTO_INCREMENT=262 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

