--
-- Table structure for table `personal_emergencias`
--

DROP TABLE IF EXISTS `personal_emergencias`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `personal_emergencias` (
  `id_personal` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'PK: Identificador de registro de personal',
  `id_usuario` bigint(20) NOT NULL COMMENT 'FK → usuarios(id_usuario)',
  `id_centro` int(11) NOT NULL COMMENT 'FK → centros_salud(id_centro)',
  `rol_emergencia` varchar(100) NOT NULL COMMENT 'Rol en emergencia (p. ej. COORDINADOR, JEFE_BRIGADA)',
  `disponibilidad` enum('DISPONIBLE','EN_SERVICIO','NO_DISPONIBLE') NOT NULL DEFAULT 'NO_DISPONIBLE' COMMENT 'Estado de disponibilidad',
  `certificacion_vigente` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1=certificado vigente, 0=no',
  `tiempo_respuesta_promedio` int(11) NOT NULL DEFAULT 0 COMMENT 'Promedio de respuesta (minutos)',
  `ubicacion_actual` varchar(255) DEFAULT NULL COMMENT 'Ubicación física/área de trabajo',
  `telefono_emergencia` varchar(20) DEFAULT NULL COMMENT 'Teléfono o radio para contacto',
  `fecha_ingreso` datetime DEFAULT NULL COMMENT 'Fecha de asignación inicial',
  `activo` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1=activo, 0=inactivo (ocultar sin borrar)',
  `fecha_creacion` datetime NOT NULL DEFAULT current_timestamp() COMMENT 'Fecha creación del registro',
  `fecha_actualizacion` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'Última modificación del registro',
  `created_by` bigint(20) DEFAULT NULL COMMENT 'FK → usuarios(id_usuario) que creó este registro',
  `updated_by` bigint(20) DEFAULT NULL COMMENT 'FK → usuarios(id_usuario) que actualizó este registro',
  PRIMARY KEY (`id_personal`),
  KEY `idx_pre_id_usuario` (`id_usuario`),
  KEY `idx_pre_id_centro` (`id_centro`),
  KEY `idx_pre_disponibilidad` (`disponibilidad`),
  KEY `idx_pre_certificacion` (`certificacion_vigente`),
  KEY `idx_pre_activo` (`activo`),
  KEY `idx_pre_created_by` (`created_by`),
  KEY `idx_pre_updated_by` (`updated_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Registro de personal de emergencia, con disponibilidad y métricas';
/*!40101 SET character_set_client = @saved_cs_client */;

