INSERT INTO `plantillas_respuesta` VALUES (1,'Bienvenida Nuevo Ticket','Hemos recibido tu ticket #{numero_ticket}','Estimado/a {nombre_usuario},\n\nHemos recibido tu ticket #{numero_ticket} y lo hemos asignado a nuestro equipo técnico.\n\nResumen de tu consulta:\nTítulo: {titulo_ticket}\nPrioridad: {prioridad}\nCategoría: {categoria}\n\nTe contactaremos pronto con una solución.\n\nSaludos,\nEquipo de Soporte INFOGES',NULL,1,1,NULL,'2025-07-10 21:49:34','2025-07-10 21:49:34'),(2,'Solicitud Información Adicional','Necesitamos más información - Ticket #{numero_ticket}','Estimado/a {nombre_usuario},\n\nPara resolver tu ticket #{numero_ticket} necesitamos información adicional:\n\n[ESPECIFICAR QUÉ INFORMACIÓN SE NECESITA]\n\nPor favor responde a este ticket con la información solicitada.\n\nGracias por tu colaboración.\n\nSaludos,\nEquipo de Soporte INFOGES',NULL,1,1,NULL,'2025-07-10 21:49:34','2025-07-10 21:49:34'),(3,'Ticket Resuelto','Ticket #{numero_ticket} resuelto','Estimado/a {nombre_usuario},\n\nTu ticket #{numero_ticket} ha sido resuelto.\n\nSolución aplicada:\n[DESCRIBIR LA SOLUCIÓN]\n\nSi el problema persiste o tienes alguna consulta adicional, no dudes en responder a este ticket.\n\nPor favor califica nuestro servicio para ayudarnos a mejorar.\n\nSaludos,\nEquipo de Soporte INFOGES',NULL,1,1,NULL,'2025-07-10 21:49:34','2025-07-10 21:49:34'),(4,'Escalamiento Ticket','Ticket #{numero_ticket} escalado a nivel superior','Estimado/a {nombre_usuario},\n\nTu ticket #{numero_ticket} ha sido escalado a nuestro equipo especializado debido a la complejidad del problema.\n\nUn técnico senior se hará cargo y te contactará en las próximas horas.\n\nApreciamos tu paciencia.\n\nSaludos,\nEquipo de Soporte INFOGES',NULL,1,0,NULL,'2025-07-10 21:49:34','2025-07-10 21:49:34'),(5,'Mantenimiento Programado','Mantenimiento programado del sistema','Estimados usuarios,\n\nLes informamos que se realizará mantenimiento programado del sistema INFOGES:\n\nFecha: {fecha_mantenimiento}\nHora: {hora_inicio} - {hora_fin}\nServicios afectados: {servicios}\n\nDurante este período algunas funcionalidades podrían no estar disponibles.\n\nGracias por su comprensión.\n\nEquipo de Soporte INFOGES',NULL,1,0,NULL,'2025-07-10 21:49:34','2025-07-10 21:49:34');
/*!40000 ALTER TABLE `plantillas_respuesta` ENABLE KEYS */;
UNLOCK TABLES;

