  `notificaciones_push` tinyint(1) DEFAULT 1,
  `notificaciones_email` tinyint(1) DEFAULT 0,
  `corrector_ia_activo` tinyint(1) DEFAULT 1,
  `tema_chat` enum('claro','oscuro','auto') DEFAULT 'claro',
  `tamaño_fuente` enum('pequeño','normal','grande') DEFAULT 'normal',
  `mostrar_hora_mensajes` tinyint(1) DEFAULT 1,
  `confirmacion_lectura` tinyint(1) DEFAULT 1,
  `auto_descarga_archivos` tinyint(1) DEFAULT 0,
  `max_conversaciones_fijadas` int(11) DEFAULT 5,
  `idioma_interface` varchar(5) DEFAULT 'es',
  `fecha_creacion` timestamp NULL DEFAULT current_timestamp(),
  `fecha_actualizacion` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_preferencia`),
  UNIQUE KEY `unique_user_preferences` (`id_usuario`),
  KEY `idx_usuario` (`id_usuario`)
) ENGINE=InnoDB AUTO_INCREMENT=1205 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
