INSERT INTO `recuerdos` VALUES (1,1,6,'EQUIPO DE SOME 2024','Fotografía del equipo SOME en 2024, capturada en la oficina central de Santiago de Chile. Este grupo de especialistas en Social Media &#38; Engagement (SOME) se reúne para diseñar y coordinar campañas digitales innovadoras: desde el análisis de métricas hasta la creación de contenidos de alto impacto, trabajan unidos para fortalecer la presencia online de la organización y maximizar el engagement de la audiencia.','2024-10-16','uploads/recuerdos/recuerdo_682e5d9184d0d_1.jpg','[\"Equipo\",\"Trabajo\"]',0,0,'2025-05-21 23:11:13','2025-05-21 23:11:13');
