--
-- Table structure for table `registros_sincronizacion`
--

DROP TABLE IF EXISTS `registros_sincronizacion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `registros_sincronizacion` (
  `id_sincronizacion` bigint(20) NOT NULL AUTO_INCREMENT,
  `tipo_sincronizacion` varchar(50) NOT NULL,
  `hora_inicio` timestamp NOT NULL DEFAULT current_timestamp(),
  `hora_fin` timestamp NULL DEFAULT NULL,
  `estado` enum('PENDIENTE','EN_PROCESO','COMPLETADO','FALLIDO') DEFAULT 'PENDIENTE',
  `registros_procesados` int(11) DEFAULT 0,
  `registros_fallidos` int(11) DEFAULT 0,
  `mensaje_error` text DEFAULT NULL,
  `iniciado_por` bigint(20) DEFAULT NULL,
  `id_centro` int(11) DEFAULT NULL,
  `id_establecimiento` int(11) DEFAULT NULL,
  PRIMARY KEY (`id_sincronizacion`),
  KEY `iniciado_por` (`iniciado_por`),
  KEY `id_centro` (`id_centro`),
  KEY `id_establecimiento` (`id_establecimiento`),
  KEY `idx_sync_estado` (`estado`),
  KEY `idx_sync_fecha` (`hora_inicio`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

