DROP TABLE IF EXISTS `registros_sistema`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `registros_sistema` (
  `id_registro` bigint(20) NOT NULL AUTO_INCREMENT,
  `nivel_log` enum('INFO','ADVERTENCIA','ERROR','CRITICO') NOT NULL,
  `mensaje` text DEFAULT NULL,
  `contexto` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`contexto`)),
  `id_centro` int(11) DEFAULT NULL,
  `id_establecimiento` int(11) DEFAULT NULL,
  `fecha_creacion` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_registro`),
  KEY `id_centro` (`id_centro`),
  KEY `id_establecimiento` (`id_establecimiento`),
  KEY `idx_log_nivel` (`nivel_log`),
  KEY `idx_log_fecha` (`fecha_creacion`)
) ENGINE=InnoDB AUTO_INCREMENT=174 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

