DROP TABLE IF EXISTS `rem_fallas_registradas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `rem_fallas_registradas` (
  `id_falla` bigint(20) NOT NULL AUTO_INCREMENT,
  `id_centro` int(11) NOT NULL COMMENT 'Centro donde se detectó la falla',
  `id_establecimiento` int(11) DEFAULT NULL COMMENT 'Establecimiento específico (si aplica)',
  `id_rem_numero` int(11) NOT NULL COMMENT 'Número REM afectado',
  `id_tipo_error` int(11) DEFAULT NULL COMMENT 'Tipo de error clasificado',
  `ano_reporte` year(4) NOT NULL COMMENT 'Año del reporte (2024-2030)',
  `mes_reporte` tinyint(2) NOT NULL COMMENT 'Mes del reporte (1-12)',
  `seccion_afectada` varchar(100) DEFAULT NULL COMMENT 'Sección específica del REM',
  `celda_especifica` varchar(50) DEFAULT NULL COMMENT 'Celda específica si aplica',
  `descripcion_falla` text DEFAULT NULL COMMENT 'Descripción detallada de la falla',
  `valor_esperado` varchar(200) DEFAULT NULL COMMENT 'Valor que debería tener',
  `valor_encontrado` varchar(200) DEFAULT NULL COMMENT 'Valor incorrecto encontrado',
  `impacto_estimado` enum('BAJO','MEDIO','ALTO','CRITICO') DEFAULT 'MEDIO' COMMENT 'Impacto estimado',
  `estado_resolucion` enum('PENDIENTE','EN_PROCESO','RESUELTO','NO_APLICA') DEFAULT 'PENDIENTE',
  `prioridad_correccion` enum('BAJA','NORMAL','ALTA','URGENTE') DEFAULT 'NORMAL',
  `id_usuario_registro` bigint(20) NOT NULL COMMENT 'Usuario que registró la falla',
  `id_usuario_asignado` bigint(20) DEFAULT NULL COMMENT 'Usuario asignado para resolver',
  `fecha_deteccion` date DEFAULT NULL COMMENT 'Fecha en que se detectó la falla',
  `fecha_limite_resolucion` date DEFAULT NULL COMMENT 'Fecha límite para resolver',
  `fecha_resolucion` datetime DEFAULT NULL COMMENT 'Fecha y hora de resolución',
  `observaciones_resolucion` text DEFAULT NULL COMMENT 'Observaciones de la resolución',
  `archivos_adjuntos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'URLs de archivos adjuntos en JSON' CHECK (json_valid(`archivos_adjuntos`)),
  `metadata_adicional` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Metadatos adicionales en formato JSON' CHECK (json_valid(`metadata_adicional`)),
  `ip_registro` varchar(45) DEFAULT NULL COMMENT 'IP desde donde se registró',
  `user_agent` text DEFAULT NULL COMMENT 'User agent del navegador',
  `fecha_creacion` timestamp NOT NULL DEFAULT current_timestamp(),
  `fecha_actualizacion` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_falla`),
  KEY `idx_centro_mes_ano` (`id_centro`,`mes_reporte`,`ano_reporte`),
  KEY `idx_establecimiento` (`id_establecimiento`),
  KEY `idx_rem_numero` (`id_rem_numero`),
  KEY `idx_tipo_error` (`id_tipo_error`),
  KEY `idx_estado_resolucion` (`estado_resolucion`),
  KEY `idx_prioridad` (`prioridad_correccion`),
  KEY `idx_usuario_registro` (`id_usuario_registro`),
  KEY `idx_usuario_asignado` (`id_usuario_asignado`),
  KEY `idx_fecha_deteccion` (`fecha_deteccion`),
  KEY `idx_fecha_limite` (`fecha_limite_resolucion`),
  KEY `idx_impacto` (`impacto_estimado`),
  KEY `idx_ano_mes` (`ano_reporte`,`mes_reporte`),
  KEY `idx_fallas_centro_ano_mes_estado` (`id_centro`,`ano_reporte`,`mes_reporte`,`estado_resolucion`),
  KEY `idx_fallas_usuario_fecha` (`id_usuario_registro`,`fecha_creacion`),
  KEY `idx_fallas_rem_severidad` (`id_rem_numero`,`impacto_estimado`),
  KEY `idx_fallas_establecimiento_ano` (`id_establecimiento`,`ano_reporte`),
  KEY `idx_fallas_tipo_error_estado` (`id_tipo_error`,`estado_resolucion`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

