--
-- Table structure for table `resultados_metas_mensuales`
--

DROP TABLE IF EXISTS `resultados_metas_mensuales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `resultados_metas_mensuales` (
  `id_resultado` bigint(20) NOT NULL AUTO_INCREMENT,
  `id_indicador` int(11) NOT NULL,
  `id_centro` int(11) NOT NULL,
  `id_establecimiento` int(11) DEFAULT NULL,
  `anio` year(4) NOT NULL,
  `mes` tinyint(4) NOT NULL CHECK (`mes` between 1 and 12),
  `numerador` decimal(15,4) NOT NULL DEFAULT 0.0000,
  `denominador` decimal(15,4) NOT NULL DEFAULT 1.0000,
  `resultado_calculado` decimal(15,4) GENERATED ALWAYS AS (case when `denominador` = 0 or `denominador` is null then 0 else `numerador` / `denominador` * 100 end) STORED,
  `valor_meta` decimal(8,4) NOT NULL,
  `ponderacion` decimal(5,2) NOT NULL DEFAULT 100.00,
  `porcentaje_cumplimiento` decimal(10,6) GENERATED ALWAYS AS (case when `valor_meta` = 0 or `valor_meta` is null then 0 else `resultado_calculado` / `valor_meta` * 100 end) STORED,
  `estado_validacion` enum('PENDIENTE','VALIDADO','RECHAZADO') NOT NULL DEFAULT 'PENDIENTE',
  `observaciones` text DEFAULT NULL,
  `fuente_dato` varchar(255) DEFAULT NULL,
  `registrado_por` bigint(20) NOT NULL,
  `fecha_registro` timestamp NOT NULL DEFAULT current_timestamp(),
  `fecha_actualizacion` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_resultado`),
  UNIQUE KEY `uk_resultado_unico` (`id_indicador`,`id_centro`,`id_establecimiento`,`anio`,`mes`),
  KEY `id_establecimiento` (`id_establecimiento`),
  KEY `registrado_por` (`registrado_por`),
  KEY `idx_indicador_periodo` (`id_indicador`,`anio`,`mes`),
  KEY `idx_centro_periodo` (`id_centro`,`anio`,`mes`),
  KEY `idx_validacion_fecha` (`estado_validacion`,`fecha_registro`),
  KEY `idx_cumplimiento` (`porcentaje_cumplimiento`),
  KEY `idx_periodo_completo` (`anio`,`mes`,`estado_validacion`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Resultados mensuales de indicadores de metas sanitarias';
/*!40101 SET character_set_client = @saved_cs_client */;

