--
-- Table structure for table `sensores_iot`
--

DROP TABLE IF EXISTS `sensores_iot`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sensores_iot` (
  `id_sensor` bigint(20) NOT NULL AUTO_INCREMENT COMMENT 'PK: Identificador de sensor IoT',
  `id_centro` int(11) NOT NULL COMMENT 'FK → centros_salud(id_centro)',
  `nombre_sensor` varchar(150) NOT NULL COMMENT 'Alias o descripción del sensor',
  `tipo_sensor` varchar(100) DEFAULT NULL COMMENT 'Tipo de sensor (p. ej. Temperatura, Movimiento)',
  `estado` enum('ACTIVO','INACTIVO','ALERTA','MANTENIMIENTO') NOT NULL DEFAULT 'ACTIVO' COMMENT 'Estado operativo del sensor',
  `nivel_bateria` tinyint(3) unsigned NOT NULL DEFAULT 100 COMMENT 'Porcentaje de batería (0–100)',
  `frecuencia_lectura` int(11) NOT NULL DEFAULT 60 COMMENT 'Intervalo (segundos) entre lecturas',
  `ultima_lectura` datetime NOT NULL COMMENT 'Fecha/hora de la última lectura',
  `ubicacion` varchar(255) DEFAULT NULL COMMENT 'Ubicación física del sensor',
  `activo` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Flag 1=activo, 0=inactivo',
  `fecha_instalacion` datetime DEFAULT NULL COMMENT 'Fecha de instalación del sensor',
  `fecha_creacion` datetime NOT NULL DEFAULT current_timestamp() COMMENT 'Fecha creación registro',
  `fecha_actualizacion` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT 'Última modificación',
  `created_by` bigint(20) DEFAULT NULL COMMENT 'FK → usuarios(id_usuario) creó sensor',
  `updated_by` bigint(20) DEFAULT NULL COMMENT 'FK → usuarios(id_usuario) actualizó sensor',
  PRIMARY KEY (`id_sensor`),
  KEY `idx_sio_id_centro` (`id_centro`),
  KEY `idx_sio_estado` (`estado`),
  KEY `idx_sio_nivel_bateria` (`nivel_bateria`),
  KEY `idx_sio_ultima_lectura` (`ultima_lectura`),
  KEY `idx_sio_activo` (`activo`),
  KEY `idx_sio_created_by` (`created_by`),
  KEY `idx_sio_updated_by` (`updated_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Catálogo y estado de sensores IoT por centro';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `sensores_iot`
--

LOCK TABLES `sensores_iot` WRITE;
/*!40000 ALTER TABLE `sensores_iot` DISABLE KEYS */;
/*!40000 ALTER TABLE `sensores_iot` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `servicios`
--

DROP TABLE IF EXISTS `servicios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `servicios` (
  `id_servicio` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL,
  `descripcion` text DEFAULT NULL,
  `imagen_url` varchar(255) DEFAULT NULL,
  `url_tramite` varchar(255) DEFAULT NULL,
  `tipo` enum('Presencial','Online','Mixto') NOT NULL,
  `requisitos` text DEFAULT NULL,
  `documentos_requeridos` text DEFAULT NULL,
  `tiempo_estimado` varchar(50) DEFAULT NULL,
  `costo` varchar(100) DEFAULT NULL,
  `disponible_online` tinyint(1) DEFAULT 0,
  `id_centro` int(11) DEFAULT NULL,
  `id_establecimiento` int(11) DEFAULT NULL,
  `orden` int(11) DEFAULT NULL,
  `activo` tinyint(1) DEFAULT 1,
  PRIMARY KEY (`id_servicio`),
  KEY `id_centro` (`id_centro`),
  KEY `id_establecimiento` (`id_establecimiento`),
  KEY `idx_servicios_tipo` (`tipo`),
  KEY `idx_servicios_online` (`disponible_online`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

