/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tr_seguidor_delete_update_stats` AFTER DELETE ON `social_seguidores` FOR EACH ROW BEGIN
  UPDATE social_user_stats
    SET total_seguidores = GREATEST(0, total_seguidores - 1)
    WHERE id_usuario = OLD.id_seguido;

  UPDATE social_user_stats
    SET total_siguiendo = GREATEST(0, total_siguiendo - 1)
    WHERE id_usuario = OLD.id_seguidor;
END */;;
