      (CHAR_LENGTH(NEW.texto_transcrito)
       - CHAR_LENGTH(REPLACE(NEW.texto_transcrito, ' ', '')) + 1),
    'characters_count', CHAR_LENGTH(NEW.texto_transcrito),
    'last_modified_by', @current_user_id,
    'modification_count',
      COALESCE(JSON_EXTRACT(OLD.metadata_premium, '$.modification_count'), 0) + 1,
    'last_modified_timestamp', NOW()
  );

  
  SET NEW.metadata_premium =
      JSON_MERGE_PATCH(OLD.metadata_premium, metadata_json);
END */;;
