CREATE TABLE `urgencias_comparativas` (
  `id_comparativa` bigint(20) NOT NULL AUTO_INCREMENT,
  `ano` int(11) NOT NULL,
  `periodo` varchar(20) NOT NULL COMMENT 'Semana, Mes, Trimestre, Semestre, Anual',
  `periodo_valor` varchar(10) NOT NULL COMMENT 'Número de semana, mes, trimestre, etc.',
  `fecha_inicio` date NOT NULL,
  `fecha_fin` date NOT NULL,
  `id_categoria_diagnostica` int(11) NOT NULL,
  `id_grupo_etario` int(11) NOT NULL,
  `total_demanda_hospital` int(11) NOT NULL DEFAULT 0,
  `total_atenciones_hospital` int(11) NOT NULL DEFAULT 0,
  `total_demanda_establecimientos` int(11) NOT NULL DEFAULT 0,
  `total_atenciones_establecimientos` int(11) NOT NULL DEFAULT 0,
  `porcentaje_cobertura_hospital` decimal(5,2) GENERATED ALWAYS AS (`total_atenciones_hospital` * 100.0 / nullif(`total_demanda_hospital`,0)) STORED,
  `porcentaje_cobertura_establecimientos` decimal(5,2) GENERATED ALWAYS AS (`total_atenciones_establecimientos` * 100.0 / nullif(`total_demanda_establecimientos`,0)) STORED,
  `diferencia_cobertura` decimal(5,2) GENERATED ALWAYS AS (`porcentaje_cobertura_hospital` - `porcentaje_cobertura_establecimientos`) STORED,
  `generado_por` bigint(20) DEFAULT NULL,
  `fecha_generacion` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id_comparativa`),
  UNIQUE KEY `uk_comparativa` (`ano`,`periodo`,`periodo_valor`,`id_categoria_diagnostica`,`id_grupo_etario`),
  KEY `generado_por` (`generado_por`),
  KEY `idx_comparativa_periodo` (`ano`,`periodo`,`periodo_valor`),
  KEY `idx_comparativa_categoria` (`id_categoria_diagnostica`),
  KEY `idx_comparativa_grupo` (`id_grupo_etario`)
) ENGINE=InnoDB AUTO_INCREMENT=1110700 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
