--
-- Table structure for table `urgencias_datos_hospital`
--

DROP TABLE IF EXISTS `urgencias_datos_hospital`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `urgencias_datos_hospital` (
  `id_registro` bigint(20) NOT NULL AUTO_INCREMENT,
  `id_dispositivo` int(11) NOT NULL,
  `ano` int(11) NOT NULL,
  `numero_semana` int(11) NOT NULL,
  `fecha_inicio_semana` date NOT NULL,
  `fecha_fin_semana` date NOT NULL,
  `id_categoria_diagnostica` int(11) NOT NULL,
  `id_grupo_etario` int(11) NOT NULL,
  `total_demanda` int(11) NOT NULL DEFAULT 0,
  `total_atenciones` int(11) NOT NULL DEFAULT 0,
  `porcentaje_cobertura` decimal(5,2) GENERATED ALWAYS AS (`total_atenciones` * 100.0 / nullif(`total_demanda`,0)) STORED,
  `brecha_atencion` int(11) GENERATED ALWAYS AS (`total_demanda` - `total_atenciones`) STORED,
  `tiempo_espera_promedio` int(11) DEFAULT NULL,
  `pacientes_hospitalizados` int(11) DEFAULT NULL,
  `derivaciones_externas` int(11) DEFAULT NULL,
  `gravedad_promedio` decimal(3,2) DEFAULT NULL,
  `validado` tinyint(1) DEFAULT 0,
  `validado_por` bigint(20) DEFAULT NULL,
  `fecha_validacion` timestamp NULL DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  `fecha_creacion` timestamp NOT NULL DEFAULT current_timestamp(),
  `fecha_actualizacion` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_registro`),
  UNIQUE KEY `uk_hospital_registro` (`id_dispositivo`,`ano`,`numero_semana`,`id_categoria_diagnostica`,`id_grupo_etario`),
  KEY `validado_por` (`validado_por`),
  KEY `idx_hospital_semana` (`ano`,`numero_semana`),
  KEY `idx_hospital_dispositivo` (`id_dispositivo`),
  KEY `idx_hospital_categoria` (`id_categoria_diagnostica`),
  KEY `idx_hospital_grupo` (`id_grupo_etario`),
  KEY `idx_hospital_validado` (`validado`)
) ENGINE=InnoDB AUTO_INCREMENT=1659 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

