/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `tr_actualizar_comparativas_hospital` AFTER INSERT ON `urgencias_datos_hospital` FOR EACH ROW BEGIN
  
  CALL sp_actualizar_comparativas(NEW.ano, 'Semana', CAST(NEW.numero_semana AS CHAR));

  
  SET @mes = MONTH(NEW.fecha_inicio_semana);

  
  CALL sp_actualizar_comparativas(NEW.ano, 'Mes', CAST(@mes AS CHAR));

  
  SET @trimestre = CEILING(@mes / 3);

  
  CALL sp_actualizar_comparativas(NEW.ano, 'Trimestre', CAST(@trimestre AS CHAR));

  
  SET @semestre = CEILING(@mes / 6);

  
  CALL sp_actualizar_comparativas(NEW.ano, 'Semestre', CAST(@semestre AS CHAR));

  
  CALL sp_actualizar_comparativas(NEW.ano, 'Anual', '1');
END */;;
DELIMITER ;
