DROP TABLE IF EXISTS `urgencias_datos_semanales_minsal`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `urgencias_datos_semanales_minsal` (
  `id_registro` bigint(20) NOT NULL AUTO_INCREMENT,
  `ano` int(11) NOT NULL,
  `numero_semana` int(11) NOT NULL CHECK (`numero_semana` between 1 and 53),
  `fecha_inicio_semana` date NOT NULL,
  `fecha_fin_semana` date NOT NULL,
  `id_centro` int(11) NOT NULL,
  `id_establecimiento` int(11) DEFAULT NULL,
  `codigo_establecimiento_minsal` varchar(20) DEFAULT NULL,
  `id_grupo_etario` int(11) NOT NULL,
  `id_categoria_diagnostica` int(11) NOT NULL,
  `total_demanda` int(11) NOT NULL DEFAULT 0,
  `total_atenciones` int(11) NOT NULL DEFAULT 0,
  `porcentaje_cobertura` decimal(5,2) GENERATED ALWAYS AS (case when `total_demanda` > 0 then `total_atenciones` * 100.0 / `total_demanda` else 0 end) STORED,
  `brecha_atencion` int(11) GENERATED ALWAYS AS (`total_demanda` - `total_atenciones`) STORED,
  `fuente_dato` enum('MINSAL_AUTOMATICO','MINSAL_MANUAL','SISTEMA_LOCAL') DEFAULT 'MINSAL_AUTOMATICO',
  `archivo_origen` varchar(255) DEFAULT NULL,
  `validado` tinyint(1) DEFAULT 0,
  `observaciones` text DEFAULT NULL,
  `registrado_por` bigint(20) NOT NULL,
  `fecha_registro` timestamp NOT NULL DEFAULT current_timestamp(),
  `fecha_actualizacion` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_registro`),
  UNIQUE KEY `uk_registro_unico` (`id_centro`,`id_establecimiento`,`ano`,`numero_semana`,`id_grupo_etario`,`id_categoria_diagnostica`),
  KEY `id_establecimiento` (`id_establecimiento`),
  KEY `id_categoria_diagnostica` (`id_categoria_diagnostica`),
  KEY `registrado_por` (`registrado_por`),
  KEY `idx_temporal` (`ano`,`numero_semana`,`id_centro`),
  KEY `idx_centro_categoria` (`id_centro`,`id_categoria_diagnostica`,`ano`),
  KEY `idx_grupo_etario_temporal` (`id_grupo_etario`,`ano`,`numero_semana`),
  KEY `idx_validacion` (`validado`,`fecha_registro`),
  KEY `idx_cobertura` (`porcentaje_cobertura`),
  KEY `idx_fuente` (`fuente_dato`,`validado`),
  KEY `idx_datos_semanales_dashboard` (`id_centro`,`ano`,`numero_semana`,`id_categoria_diagnostica`,`total_atenciones`)
) ENGINE=InnoDB AUTO_INCREMENT=506 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
