  `parametros_calculo` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`parametros_calculo`)),
  PRIMARY KEY (`id_metrica`),
  UNIQUE KEY `uk_cache_metrica` (`tipo_metrica`,`id_centro`,`ano`,`numero_semana`),
  KEY `id_centro` (`id_centro`),
  KEY `idx_expiracion` (`fecha_expiracion`),
  KEY `idx_tipo_periodo` (`tipo_metrica`,`ano`,`numero_semana`)
