  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `action` varchar(100) NOT NULL,
  `module_id` int(11) DEFAULT NULL COMMENT 'Módulo accedido',
  `ip_address` varchar(45) NOT NULL,
  `user_agent` text DEFAULT NULL,
  `timestamp` timestamp NULL DEFAULT current_timestamp(),
  `last_activity` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `session_duration` int(11) DEFAULT NULL COMMENT 'Duración de la sesión en segundos',
  `additional_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Datos adicionales de la actividad' CHECK (json_valid(`additional_data`)),
  PRIMARY KEY (`id`),
  KEY `idx_user_activity` (`user_id`,`last_activity`),
  KEY `idx_activity_timestamp` (`timestamp`),
  KEY `idx_activity_module` (`module_id`,`timestamp`),
  KEY `idx_activity_action` (`action`,`timestamp`)
) ENGINE=InnoDB AUTO_INCREMENT=948 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Registro de actividad de usuarios en el sistema';
