DROP TABLE IF EXISTS `user_preferences`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `user_preferences` (
  `id_preference` int(11) NOT NULL AUTO_INCREMENT,
  `id_usuario` bigint(20) NOT NULL,
  `categoria` varchar(50) NOT NULL,
  `clave` varchar(100) NOT NULL,
  `valor` longtext NOT NULL,
  `tipo_dato` enum('string','integer','boolean','json','decimal') DEFAULT 'string',
  `descripcion` text DEFAULT NULL,
  `es_editable` tinyint(1) DEFAULT 1,
  `fecha_creacion` timestamp NOT NULL DEFAULT current_timestamp(),
  `fecha_actualizacion` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id_preference`),
  UNIQUE KEY `unique_user_preference` (`id_usuario`,`categoria`,`clave`),
  KEY `idx_usuario_preferences` (`id_usuario`),
  KEY `idx_categoria` (`categoria`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
