--
-- Table structure for table `usuarios`
--

DROP TABLE IF EXISTS `usuarios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `usuarios` (
  `id_usuario` bigint(20) NOT NULL AUTO_INCREMENT,
  `nombre_usuario` varchar(50) NOT NULL,
  `correo` varchar(100) NOT NULL,
  `contrasena_hash` varchar(255) NOT NULL,
  `remember_token` varchar(64) DEFAULT NULL,
  `nombres` varchar(50) NOT NULL,
  `apellidos` varchar(50) NOT NULL,
  `avatar` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `rut` varchar(12) NOT NULL,
  `foto_perfil` varchar(255) DEFAULT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `extension_telefonica` varchar(10) DEFAULT NULL,
  `activo` tinyint(1) DEFAULT 1,
  `fecha_creacion` timestamp NOT NULL DEFAULT current_timestamp(),
  `fecha_actualizacion` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `ultimo_acceso` timestamp NULL DEFAULT NULL,
  `forzar_cambio_contrasena` tinyint(1) DEFAULT 1,
  `intentos_fallidos` int(11) DEFAULT 0,
  `bloqueado_hasta` timestamp NULL DEFAULT NULL,
  `token_recuperacion` varchar(64) DEFAULT NULL,
  `token_expira` datetime DEFAULT NULL,
  `fecha_modificacion` datetime DEFAULT NULL,
  `fecha_token` datetime DEFAULT NULL,
  `requiere_cambio_password` tinyint(1) DEFAULT 0,
  `fecha_nacimiento` date DEFAULT NULL,
  `id_centro` int(11) DEFAULT NULL,
  `id_establecimiento` int(11) DEFAULT NULL,
  `direccion` varchar(255) DEFAULT NULL,
  `plan_premium` varchar(50) NOT NULL DEFAULT 'Básico',
  `transcripciones_restantes` int(11) NOT NULL DEFAULT 0,
  `cargo` varchar(100) DEFAULT NULL,
  `estamento` enum('profesional','tecnico','administrativo','auxiliar','directivo','Med-Qui-Odon') DEFAULT NULL,
  `categoria` enum('A','B','C','D','E','F') DEFAULT NULL,
  `grado` smallint(5) unsigned DEFAULT NULL,
  `profesion` varchar(120) DEFAULT NULL,
  `especialidad` varchar(120) DEFAULT NULL,
  `fecha_ingreso` date DEFAULT NULL,
  `tipo_contrato` enum('indefinido','plazo_fijo','honorarios','practica','reemplazo') DEFAULT NULL,
  `horas_semanales` tinyint(3) unsigned DEFAULT NULL,
  `jornada_laboral` enum('diurna','vespertina','nocturna','mixta','turnos') DEFAULT NULL,
  `en_turno` tinyint(3) unsigned DEFAULT NULL,
  `fecha_termino_contrato` date DEFAULT NULL,
  `nivel_educacional` enum('basica','media','tecnica','profesional','magister','doctorado','postitulo') DEFAULT NULL,
  `nacionalidad` varchar(60) DEFAULT NULL,
  `genero` enum('masculino','femenino','otro','no_informa') DEFAULT NULL,
  `estado_civil` varchar(255) DEFAULT NULL,
  `empresa` varchar(150) DEFAULT NULL,
  `estado_conexion` enum('online','offline','away','busy') NOT NULL DEFAULT 'offline',
  `disponible_videollamadas` tinyint(1) NOT NULL DEFAULT 0,
  `ultima_actividad` datetime DEFAULT NULL,
  `mensaje_estado` varchar(200) DEFAULT NULL,
  `dispositivo_preferido_camara` varchar(100) DEFAULT NULL,
  `dispositivo_preferido_microfono` varchar(100) DEFAULT NULL,
  `dispositivo_preferido_altavoces` varchar(100) DEFAULT NULL,
  `calidad_video_preferida` enum('low','medium','high','ultra') DEFAULT 'medium',
  `notificaciones_videollamadas` tinyint(1) DEFAULT 1,
  `sonido_llamadas` tinyint(1) DEFAULT 1,
  `grabacion_automatica` tinyint(1) DEFAULT 0,
  `telefono_extension` varchar(10) DEFAULT NULL COMMENT 'Extensión telefónica',
  `estado_llamadas` enum('disponible','ocupado','no_molestar','ausente') DEFAULT 'disponible',
  `calidad_audio_preferida` enum('low','medium','high','ultra') DEFAULT 'high',
  `fecha_nacimiento_mes_dia` char(5) DEFAULT NULL,
  PRIMARY KEY (`id_usuario`),
  UNIQUE KEY `nombre_usuario` (`nombre_usuario`),
  UNIQUE KEY `correo` (`correo`),
  UNIQUE KEY `rut` (`rut`),
  KEY `idx_usuario_correo` (`correo`),
  KEY `idx_usuario_rut` (`rut`),
  KEY `id_centro` (`id_centro`),
  KEY `idx_usuarios_email_activo` (`correo`,`activo`),
  KEY `idx_usuarios_activo_bloqueado` (`activo`,`bloqueado_hasta`),
  KEY `idx_estado_conexion` (`estado_conexion`),
  KEY `idx_disponible_videollamadas` (`disponible_videollamadas`),
  KEY `idx_ultima_actividad` (`ultima_actividad`),
  KEY `idx_activo_conexion` (`activo`,`estado_conexion`),
  KEY `idx_extension` (`extension_telefonica`),
  KEY `idx_estamento` (`estamento`),
  KEY `idx_categoria` (`categoria`),
  KEY `idx_grado` (`grado`),
  KEY `idx_tipo_contrato` (`tipo_contrato`),
  KEY `idx_jornada_laboral` (`jornada_laboral`),
  KEY `idx_usuarios_fecha_nacimiento_mes_dia` (`fecha_nacimiento_mes_dia`)
) ENGINE=InnoDB AUTO_INCREMENT=1424 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

