  `duracion_segundos` int(11) NOT NULL DEFAULT 0 COMMENT 'Duración en segundos',
  `tiempo_espera_segundos` int(11) NOT NULL DEFAULT 0 COMMENT 'Espera antes de conectar',
  `estado` enum('iniciada','sonando','conectando','conectada','terminada','perdida','rechazada','cancelada','error','timeout') NOT NULL DEFAULT 'iniciada' COMMENT 'Estado actual',
  `calidad_configurada` enum('low','medium','high','ultra') NOT NULL DEFAULT 'medium',
  `calidad_real` enum('excellent','good','fair','poor') DEFAULT NULL,
  `calificacion_calidad` tinyint(1) DEFAULT NULL,
  `tipo_llamada` enum('video','audio','screen_share') NOT NULL DEFAULT 'video' COMMENT 'Tipo de llamada',
  `calidad_conexion` enum('excelente','buena','regular','mala','muy_mala') DEFAULT NULL COMMENT 'Calidad',
  `resolucion_video` varchar(20) DEFAULT NULL COMMENT 'Resolución (e.g. 1280x720)',
  `framerate` int(3) DEFAULT NULL,
  `fps_video` tinyint(3) DEFAULT NULL COMMENT 'FPS del video',
  `bitrate_video` int(11) DEFAULT NULL COMMENT 'Bitrate video kbps',
  `bitrate_audio` int(11) DEFAULT NULL COMMENT 'Bitrate audio kbps',
  `dispositivo_emisor` text DEFAULT NULL COMMENT 'Dispositivo emisor (JSON)',
  `dispositivo_receptor` text DEFAULT NULL COMMENT 'Dispositivo receptor (JSON)',
  `ip_emisor` varchar(45) DEFAULT NULL COMMENT 'IP emisor',
  `ip_receptor` varchar(45) DEFAULT NULL COMMENT 'IP receptor',
  `user_agent` text DEFAULT NULL,
  `bandwidth_usado` int(11) DEFAULT NULL,
  `perdida_paquetes` decimal(5,2) DEFAULT NULL,
  `ubicacion_emisor` varchar(100) DEFAULT NULL COMMENT 'Ubicación emisor',
  `ubicacion_receptor` varchar(100) DEFAULT NULL COMMENT 'Ubicación receptor',
  `codec_video` varchar(50) DEFAULT NULL COMMENT 'Códec video',
  `codec_audio` varchar(50) DEFAULT NULL COMMENT 'Códec audio',
  `latencia_promedio` int(11) DEFAULT NULL COMMENT 'Latencia ms',
  `paquetes_perdidos` int(11) NOT NULL DEFAULT 0 COMMENT 'Paquetes perdidos',
  `porcentaje_perdida` decimal(5,2) NOT NULL DEFAULT 0.00 COMMENT '%% pérdidas',
  `compartio_pantalla` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1=compartió pantalla',
