/*!50001 VIEW `v_videollamadas_estadisticas` AS select `u`.`id_usuario` AS `id_usuario`,concat(`u`.`nombres`,' ',`u`.`apellidos`) AS `nombre_completo`,count(0) AS `total_llamadas`,count(case when `v`.`estado` = 'terminada' then 1 end) AS `llamadas_exitosas`,count(case when `v`.`estado` = 'perdida' then 1 end) AS `llamadas_perdidas`,count(case when `v`.`estado` = 'rechazada' then 1 end) AS `llamadas_rechazadas`,count(case when `v`.`id_usuario_emisor` = `u`.`id_usuario` then 1 end) AS `llamadas_realizadas`,count(case when `v`.`id_usuario_receptor` = `u`.`id_usuario` then 1 end) AS `llamadas_recibidas`,avg(case when `v`.`duracion_segundos` > 0 then `v`.`duracion_segundos` end) AS `duracion_promedio`,sum(`v`.`duracion_segundos`) AS `tiempo_total_llamadas`,max(`v`.`fecha_inicio`) AS `ultima_llamada` from (`usuarios` `u` left join `videollamadas` `v` on(`u`.`id_usuario` = `v`.`id_usuario_emisor` or `u`.`id_usuario` = `v`.`id_usuario_receptor`)) where `v`.`activo` = 1 or `v`.`id_videollamada` is null group by `u`.`id_usuario`,`u`.`nombres`,`u`.`apellidos` */;
